#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""FEYZULLAH V34.4 + GLOBAL VIDEO 8.15.1 — Render-ready single-file launcher.

Render Build Command:
python3 FEYZULLAH_GLOBAL_VIDEO_V34_4_RENDER_READY.py --prepare && pip install -r .feyzullah_runtime/requirements.txt

Render Start Command:
uvicorn FEYZULLAH_GLOBAL_VIDEO_V34_4_RENDER_READY:app --host 0.0.0.0 --port $PORT

This file extracts the complete, verified application bundle into .feyzullah_runtime
and loads the real FastAPI app. The /media route redirects to /global-video/.
"""
import argparse, base64, hashlib, importlib.util, io, sys, zipfile
from pathlib import Path, PurePosixPath
_ARCHIVE_SHA256 = '0715d15b92dddef740b893341e54476d4a0163b31aa3cbd5fed996da244cd025'
_ARCHIVE_B64 = r"""

"""
RUNTIME_DIRNAME = ".feyzullah_runtime"

def prepare():
    payload = base64.b64decode(_ARCHIVE_B64)
    if hashlib.sha256(payload).hexdigest() != _ARCHIVE_SHA256:
        raise SystemExit("Paket doğrulaması başarısız: SHA256 uyuşmuyor.")
    root = Path(__file__).resolve().parent
    target_root = (root / RUNTIME_DIRNAME).resolve()
    target_root.mkdir(parents=True, exist_ok=True)
    with zipfile.ZipFile(io.BytesIO(payload)) as archive:
        for info in archive.infolist():
            rel = PurePosixPath(info.filename)
            if rel.is_absolute() or ".." in rel.parts:
                raise SystemExit("Güvensiz arşiv yolu reddedildi.")
            target = (target_root / Path(*rel.parts)).resolve()
            if target_root not in target.parents and target != target_root:
                raise SystemExit("Arşiv hedef dizinin dışına çıkıyor.")
        archive.extractall(target_root)
    required = [target_root / "main.py", target_root / "requirements.txt",
                target_root / "global_video_runtime" / "main.py",
                target_root / "global_video_runtime" / "static" / "index.html"]
    missing = [str(p) for p in required if not p.is_file()]
    if missing:
        raise SystemExit("Paket eksik dosya içeriyor: " + ", ".join(missing))
    print("V34.4 + GLOBAL VIDEO 8.15.1 başarıyla hazırlandı.")
    print("Yeni medya arayüzü: /media ve /global-video/")
    print("Eski medya arayüzü: /media/legacy")
    print("Start: uvicorn FEYZULLAH_GLOBAL_VIDEO_V34_4_RENDER_READY:app --host 0.0.0.0 --port $PORT")

def load_app():
    runtime = Path(__file__).resolve().parent / RUNTIME_DIRNAME
    if not (runtime / "main.py").is_file():
        prepare()
    runtime = runtime.resolve()
    if str(runtime) not in sys.path:
        sys.path.insert(0, str(runtime))
    spec = importlib.util.spec_from_file_location("_feyzullah_v34_runtime_main", runtime / "main.py")
    if spec is None or spec.loader is None:
        raise RuntimeError("Paket içindeki gerçek main.py yüklenemedi.")
    module = importlib.util.module_from_spec(spec)
    sys.modules[spec.name] = module
    spec.loader.exec_module(module)
    if not hasattr(module, "app"):
        raise RuntimeError("Paket içindeki gerçek uygulamada FastAPI app bulunamadı.")
    return module.app

if __name__ == "__main__":
    parser = argparse.ArgumentParser(description="FEYZULLAH V34.4 Render dağıtımı")
    parser.add_argument("--prepare", action="store_true")
    args = parser.parse_args()
    if args.prepare:
        prepare()
    else:
        parser.print_help()
else:
    app = load_app()
